// Structured data (schema.org JSON-LD) and social preview images.
// Every fact here comes from data/profile.json (and its Japanese wording overlay); never add
// claims that the profile lacks.
import profile from '../../data/profile.json';
import { getProfile } from '../i18n/content';
import { homePath, type Locale } from '../i18n/config';

export const SITE_NAME = profile.name;
export const OG_IMAGE_WIDTH = 1200;
export const OG_IMAGE_HEIGHT = 630;

/**
 * Social card of a page, generated by `npm run og:generate` (scripts/generate-og-images.mjs).
 * `key` is `home` or a case study's OG key (see caseStudyOgKey).
 */
export const ogImagePath = (key: string, locale: Locale) => `/og/${key}-${locale}.png`;

/** OG key of a case study: the first word of its slug (`kafka-event-architecture` -> `kafka`). */
export const caseStudyOgKey = (slug: string) => slug.split('-')[0];

/** Core backend stack for `knowsAbout`, all from data/profile.json skills. */
const coreStack = [
  'Node.js',
  'TypeScript',
  'NestJS',
  'Express.js',
  'GraphQL Federation',
  'REST APIs',
  'MongoDB',
  'MSSQL',
  'PostgreSQL',
  'Redis',
  'Apache Kafka',
  'RabbitMQ',
  'Kubernetes',
  'Docker',
  'AWS EC2',
];
const allSkills: string[] = Object.values(profile.skills).flat();
const knowsAbout = coreStack.filter((s) => allSkills.includes(s));

const current = profile.experience.find((e) => e.current);
// "Bengaluru, India" -> locality + country
const [locality, country] = profile.location.split(',').map((s) => s.trim());

const siteRoot = (siteUrl: string) => `${siteUrl.replace(/\/$/, '')}/`;
export const personId = (siteUrl: string) => `${siteRoot(siteUrl)}#person`;
export const websiteId = (siteUrl: string) => `${siteRoot(siteUrl)}#website`;

/** The site owner, in the page's language. */
export function person(siteUrl: string, locale: Locale) {
  const p = getProfile(locale);
  return {
    '@type': 'Person',
    '@id': personId(siteUrl),
    name: profile.name,
    jobTitle: p.title,
    url: new URL(homePath(locale), siteUrl).toString(),
    ...(current && { worksFor: { '@type': 'Organization', name: current.company } }),
    address: {
      '@type': 'PostalAddress',
      addressLocality: locality,
      ...(country && { addressCountry: country }),
    },
    sameAs: [profile.links.github, profile.links.linkedin],
    knowsAbout,
    alumniOf: profile.education.map((e) => ({
      '@type': e.type === 'degree' ? 'CollegeOrUniversity' : 'EducationalOrganization',
      name: e.institution,
    })),
  };
}

const website = (siteUrl: string) => ({
  '@type': 'WebSite',
  '@id': websiteId(siteUrl),
  name: SITE_NAME,
  url: siteRoot(siteUrl),
  inLanguage: ['en', 'ja'],
});

interface PageMeta {
  siteUrl: string;
  pageUrl: string;
  locale: Locale;
  title: string;
  description: string;
  image: string;
}

const imageObject = (url: string) => ({
  '@type': 'ImageObject',
  url,
  width: OG_IMAGE_WIDTH,
  height: OG_IMAGE_HEIGHT,
});

/** Home page (`/`, `/ja/`): a ProfilePage about the site owner. */
export function profilePageJsonLd({
  siteUrl,
  pageUrl,
  locale,
  title,
  description,
  image,
}: PageMeta) {
  return {
    '@context': 'https://schema.org',
    '@type': 'ProfilePage',
    '@id': `${pageUrl}#profilepage`,
    url: pageUrl,
    name: title,
    description,
    inLanguage: locale,
    primaryImageOfPage: imageObject(image),
    isPartOf: website(siteUrl),
    mainEntity: person(siteUrl, locale),
  };
}

/** Case study pages: a TechArticle written by the site owner. */
export function techArticleJsonLd(meta: PageMeta & { datePublished: Date; keywords: string[] }) {
  const { siteUrl, pageUrl, locale, title, description, image } = meta;
  const author = person(siteUrl, locale);
  return {
    '@context': 'https://schema.org',
    '@type': 'TechArticle',
    '@id': `${pageUrl}#article`,
    headline: title,
    description,
    url: pageUrl,
    mainEntityOfPage: { '@type': 'WebPage', '@id': pageUrl },
    inLanguage: locale,
    datePublished: meta.datePublished.toISOString(),
    keywords: meta.keywords.join(', '),
    image: imageObject(image),
    author: { '@type': 'Person', '@id': author['@id'], name: author.name, url: author.url },
    publisher: { '@type': 'Person', '@id': author['@id'], name: author.name },
    isPartOf: website(siteUrl),
  };
}
